{"command": "python3 <<'PY'
import subprocess

# Implement bech32 encode (BIP173) to generate valid recipients
CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

def bech32_polymod(values):
    GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
    chk = 1
    for v in values:
        b = (chk >> 25)
        chk = (chk & 0x1ffffff) << 5 ^ v
        for i in range(5):
            chk ^= GEN[i] if ((b >> i) & 1) else 0
    return chk

def bech32_hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]

def bech32_create_checksum(hrp, data):
    values = bech32_hrp_expand(hrp) + data
    polymod = bech32_polymod(values + [0,0,0,0,0,0]) ^ 1
    return [(polymod >> 5*(5-i)) & 31 for i in range(6)]

def bech32_encode(hrp, data):
    # data is list of 5-bit values
    combined = data + bech32_create_checksum(hrp, data)
    return hrp + '1' + ''.join([CHARSET[d] for d in combined])

def convertbits(data, frombits, tobits, pad=True):
    acc = 0
    bits = 0
    ret = []
    maxv = (1 << tobits) - 1
    max_acc = (1 << (frombits + tobits - 1)) - 1
    for value in data:
        acc = ((acc << frombits) | value) & max_acc
        bits += frombits
        while bits >= tobits:
            bits -= tobits
            ret.append((acc >> bits) & maxv)
    if pad:
        if bits:
            ret.append((acc << (tobits - bits)) & maxv)
    elif bits >= frombits or ((acc << (tobits - bits)) & maxv):
        return None
    return ret

def encode_age(hrp, raw_bytes):
    data = convertbits(list(raw_bytes), 8, 5, True)
    return bech32_encode(hrp, data)

import os, subprocess

def test_recip(recip):
    p=subprocess.run(["./executable","-r",recip], input=b"hello", capture_output=True)
    return p.returncode, p.stderr[:500]

# Test classic age HRP with 32 bytes
for l in [16, 31, 32, 33, 64]:
    r=encode_age("age", os.urandom(l))
    rc,err=test_recip(r)
    print(f"age len {l} => rc={rc} err={err[:200]!r} recip={r[:30]}...")

# Test tag HRPs
for hrp in ["age1tag", "age1tagpq", "age1pq", "age1foo"]:
    for l in [32, 33, 64, 65, 1184, 1216, 1217, 1184+32, 1184+33]:
        r=encode_age(hrp, os.urandom(l))
        rc,err=test_recip(r)
        # Only print interesting (rc==0 or different error)
        print(f"{hrp} len {l} => rc={rc} err={err[:300]!r}")
    print("---")
PY
"}

