	fs.Var(hHelp, "help", "")
	fs.BoolVar(&versionFlag, "version", false, "")
	fs.StringVar(&output, "o", "", "")
	fs.StringVar(&output, "output", "", "")
	fs.Var(&recipients, "r", "")
	fs.Var(&recipients, "recipient", "")
	fs.Var(&recipientsFiles, "R", "")
	fs.Var(&recipientsFiles, "recipients-file", "")
	fs.Var(&identities, "i", "")
	fs.Var(&identities, "identity", "")
