package main

import (
	"fmt"
	"strings"
)

const bech32Charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

func bech32Polymod(values []int) int {
	gen := []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = (chk&0x1ffffff)<<5 ^ v
		for i := 0; i < 5; i++ {
			if (b>>i)&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func bech32HrpExpand(hrp string) []int {
	var ret []int
	for _, c := range hrp {
		ret = append(ret, int(c>>5))
	}
	ret = append(ret, 0)
	for _, c := range hrp {
		ret = append(ret, int(c&31))
	}
	return ret
}

func bech32VerifyChecksum(hrp string, data []int) bool {
	combined := append(bech32HrpExpand(hrp), data...)
	return bech32Polymod(combined) == 1
}

func bech32CreateChecksum(hrp string, data []int) []int {
	values := append(bech32HrpExpand(hrp), data...)
	values = append(values, 0, 0, 0, 0, 0, 0)
	polymod := bech32Polymod(values) ^ 1
	var ret []int
	for i := 0; i < 6; i++ {
		ret = append(ret, (polymod>>(5*(5-i)))&31)
	}
	return ret
}

func convertBits(data []byte, fromBits, toBits int, pad bool) ([]int, error) {
	acc := 0
	bits := 0
	var ret []int
	maxv := (1 << toBits) - 1
	maxAcc := (1 << (fromBits + toBits - 1)) - 1
	for _, value := range data {
		acc = ((acc << fromBits) | int(value)) & maxAcc
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			ret = append(ret, (acc>>bits)&maxv)
		}
	}
	if pad {
		if bits > 0 {
			ret = append(ret, (acc<<(toBits-bits))&maxv)
		}
	} else if bits >= fromBits || ((acc<<(toBits-bits))&maxv) != 0 {
		return nil, fmt.Errorf("invalid padding")
	}
	return ret, nil
}

func convertBits5to8(data []int) ([]byte, error) {
	acc := 0
	bits := 0
	var ret []byte
	for _, value := range data {
		acc = (acc<<5 | value)
		bits += 5
		for bits >= 8 {
			bits -= 8
			ret = append(ret, byte((acc>>bits)&0xff))
		}
	}
	return ret, nil
}

func bech32Decode(s string) (string, []int, error) {
	hasLower := false
	hasUpper := false
	for _, c := range s {
		if c >= 'a' && c <= 'z' {
			hasLower = true
		}
		if c >= 'A' && c <= 'Z' {
			hasUpper = true
		}
	}
	if hasLower && hasUpper {
		return "", nil, fmt.Errorf("mixed case")
	}
	pos := strings.LastIndex(s, "1")
	if pos == -1 {
		return "", nil, fmt.Errorf("separator '1' at invalid position: pos=-1, len=%d", len(s))
	}
	if pos < 1 || pos+7 > len(s) {
		return "", nil, fmt.Errorf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	hrp := s[:pos]
	dataPart := s[pos+1:]
	for i, c := range hrp {
		if c < 33 || c > 126 {
			return "", nil, fmt.Errorf("invalid character human-readable part: s[%d]=%d", i, c)
		}
	}
	isUpper := hasUpper && !hasLower
	for i, c := range dataPart {
		sIdx := pos + 1 + i
		var inCharset bool
		if isUpper {
			for _, cc := range strings.ToUpper(bech32Charset) {
				if c == cc {
					inCharset = true
					break
				}
			}
		} else {
			for _, cc := range bech32Charset {
				if c == cc {
					inCharset = true
					break
				}
			}
		}
		if !inCharset {
			return "", nil, fmt.Errorf("invalid character data part: s[%d]=%d", sIdx, c)
		}
	}
	var data5 []int
	for _, c := range dataPart {
		lower := c
		if c >= 'A' && c <= 'Z' {
			lower = c + 32
		}
		for i, cc := range bech32Charset {
			if byte(cc) == byte(lower) {
				data5 = append(data5, i)
				break
			}
		}
	}
	if !bech32VerifyChecksum(strings.ToLower(hrp), data5) {
		return "", nil, fmt.Errorf("invalid checksum")
	}
	return hrp, data5[:len(data5)-6], nil
}

func bech32Encode(hrp string, data []byte) string {
	data5, _ := convertBits(data, 8, 5, true)
	checksum := bech32CreateChecksum(strings.ToLower(hrp), data5)
	combined := append(data5, checksum...)
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteString("1")
	for _, v := range combined {
		sb.WriteByte(bech32Charset[v])
	}
	s := sb.String()
	hasUpper := false
	for _, c := range hrp {
		if c >= 'A' && c <= 'Z' {
			hasUpper = true
			break
		}
	}
	if hasUpper {
		idx := strings.LastIndex(s, "1")
		s = s[:idx+1] + strings.ToUpper(s[idx+1:])
	}
	return s
}

func indexByte(s string, b byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == b {
			return i
		}
	}
	return -1
}
